let p; // global variable, instance of particle
let t;
let launcher;
let gotLauncher = false;

const pallet = ["#0583FE", "#EBFC44", "#12FCF5", "#00B0A9", "#A22BFC"]; //ellipse colour pallet

function setup() {
	createCanvas(windowWidth, windowHeight);
	background('#FC752B');
	p = new Particle(width*0.03, height/3); // instantiate new particle at defined location
	t = new Target();
	blendMode(DIFFERENCE); 
}

function draw() {
	p.update();
	p.addForce(createVector(0,0.01)); // gravity

	if(gotLauncher){
		launcher.updateEnd((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		launcher.update();
	}
	t.update(p.loc); // update target and hit test
}

function mousePressed(){ // if not gotLauncher, switch to true and spawn launcher
	if(!gotLauncher){  // ! = do not, same as == false (equally equalator)
		gotLauncher = true;
		launcher = new Launcher((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
	}
}

function mouseReleased(){ // reset gotLauncher and generate particle
	background('#FC752B');
	gotLauncher = false;
	p = new Particle(launcher.end.x, launcher.end.y);
	p.addForce(launcher.getVelocity()); // make it move
}

class Launcher{
	constructor(x,y){
		this.start = createVector(x,y);
		this.end = createVector(0,0);
	}
	updateEnd(x,y){
		this.end.set(x,y);
	}
	getVelocity(){
		let v = this.start.sub(this.end);
		return v.mult(0.03);
	}
	update(){
	}
}

class Target{
	constructor(x,y){ // input for location
		this.loc = createVector(random(width),random(height));
	}
	update(hit){ // check to see if location and hit are close enough
		if(this.loc.dist(hit) < 30){
			this.loc.set(random(width),random(height)); // if hit, then reset pos
		}
	}
}

class Particle { // blueprint

	constructor (x, y){ // block is code that is first called, () = arguments, can be fed into code, member variables go inside here

		this.loc = createVector(x, y); // loc = location
		this.vel = createVector(0, 0);
	}

	addForce(force){
		this.vel.add(force); // adding force to the vel
	}

	update(){ // member method, class method | can be called inside class, and in instances with the . synthax (doesn't start with function) | can be called whatever you want, but make it make sense to you
		this.loc.add(this.vel); // add vel to the current loc and then do the below

		push();
		translate(this.loc.x, this.loc.y);
		rotate(this.vel.heading()); // rotate to heading (value and radians from start to finish)
		noStroke();
		fill(random(pallet));
		ellipse(0,0, random(100,200), random(100,200));
		pop();

		if(this.loc.y > height || this.loc.y <= 0){
			this.vel.y = -(this.vel.y); // bounce on floor
		}
		if(this.loc.x > width || this.loc.x <= 0){
			this.vel.x = -(this.vel.x); // bounce on right wall
		}
	}
}
